import type { FieldSpec } from './field.ts'

const HEADER = [
  '# Generated by `vpr app config:generate`; do not edit by hand.',
  '# Every variable below is optional: the value shown is the default.',
  '# Copy this file to `.env` and change only what you need.'
]

const describe = (spec: FieldSpec): string =>
  spec.choices === undefined ? spec.kind : `${spec.kind}: ${spec.choices.join(' | ')}`

/** Renders the example dotenv file from the configuration declarations. */
export const renderExample = (specs: readonly FieldSpec[]): string => {
  const sections = new Map<string, FieldSpec[]>()
  for (const spec of specs) {
    const title = spec.section ?? 'General'
    sections.set(title, [...(sections.get(title) ?? []), spec])
  }

  const blocks = [...sections].map(([title, fields]) => {
    const lines = fields.flatMap((spec) => [
      `# ${spec.description} (${describe(spec)})`,
      `${spec.name}=${/[\s#]/.test(spec.default) ? `"${spec.default}"` : spec.default}`,
      ''
    ])
    return [`# --- ${title} ---`, ...lines].join('\n')
  })

  return `${[HEADER.join('\n'), '', ...blocks].join('\n').trimEnd()}\n`
}
